def samples(series, feature, earliest, day, window, start=0):
    xs=[];ys=[];counts={}
    for k in range(max(earliest,day-window),day):
        stop=143 if k==day-1 else 144
        if stop<=start:continue
        x=np.asarray(feature(k))[start:stop]
        xs.append(x);ys.append(series[k,start:stop]);counts[str(k)]=len(x)
    return (np.concatenate(xs) if xs else None,
            np.concatenate(ys) if ys else None,counts)

def choose(rows, cutoff, simple_key):
    assessed=[]
    for row in rows:
        values=losses_before(row['loss_records'],cutoff)
        if not len(values):continue
        assessed.append((row,float(values.mean()),float(values.std(ddof=1)/np.sqrt(len(values))) if len(values)>1 else 0.))
    if not assessed:return min(rows,key=simple_key)
    best=min(assessed,key=lambda r:r[1]);threshold=best[1]+best[2]
    return min((r for r,m,s in assessed if m<=threshold+1e-12),key=simple_key)

