def action(net, g, s, reference, margin=RESERVE_MARGIN):
    gap = float(net - g)
    reserve = max(SOC_MIN, float(reference) - margin)
    if gap >= 0:
        d = min(gap, SLOT_ENERGY_CAP, ETA_D * max(s - reserve, 0))
        c, e, w = 0.0, max(gap - d, 0.0), 0.0
    else:
        c = min(-gap, SLOT_ENERGY_CAP, max((SOC_MAX - s) / ETA_C, 0))
        d, e, w = 0.0, 0.0, max(-gap - c, 0.0)
    return c, d, e, w, s + ETA_C * c - d / ETA_D

