def fit(X,y,prior,ridge,active=False):
    X=np.asarray(X,float).reshape(-1,len(prior));y=np.asarray(y,float).ravel()
    if active:
        m=np.maximum(y,X.max(1))>1e-8;X=X[m];y=y[m]
    if len(y)<2:return np.asarray(prior).copy()
    resid=y-X@prior;scale=max(float(np.median(abs(resid-np.median(resid)))),1e-4)
    def objective(w):
        z=(y-X@w)/scale;az=abs(z)
        loss=np.where(az<=1.345,.5*z*z,1.345*(az-.6725))
        grad=-(X.T@np.clip(z,-1.345,1.345))/(len(y)*scale)+2*ridge*(w-prior)
        return float(loss.mean()+ridge*np.sum((w-prior)**2)),grad
    r=minimize(objective,prior,jac=True,method='SLSQP',bounds=[(0,1)]*len(prior),constraints={'type':'eq','fun':lambda w:w.sum()-1,'jac':lambda w:np.ones(len(w))},options={'ftol':1e-9,'maxiter':400})
    if not r.success:
        # 此问题为凸优化；退化情形以均匀点重启，失败显式报错。
        r=minimize(objective,np.full(len(prior),1/len(prior)),jac=True,method='SLSQP',bounds=[(0,1)]*len(prior),constraints={'type':'eq','fun':lambda w:w.sum()-1},options={'ftol':1e-8,'maxiter':1000})
    if not r.success:raise RuntimeError('权重优化失败 '+r.message)
    w=np.maximum(r.x,0);return w/w.sum()

def fit_state(data,raw,historical,d,prior,ridge,window):
    state={k:np.array(v).copy() for k,v in prior.items()}
    for key,series,lags,active,earliest in [('load',data.L,(7,14),False,14),('pv',data.V,(1,2,3),True,3)]:
        X,y,_=samples(series,lambda k:np.column_stack([lag(series,k,l) for l in lags]),earliest,d,window)
        if X is not None:state[key]=fit(X,y,prior[key],ridge,active)
    for j,h in enumerate(HOURS):
        X,y,_=samples(data.V,lambda k:np.column_stack([historical[k],*raw[k,:j+1]]),3,d,window,CUTS[j])
        if X is not None:state[str(h)]=fit(X,y,prior[str(h)],ridge,True)
    return state

