class Planner:
    def __init__(self,p,target):self.p=p;self.target=target;self.count=0;self.residual=0.;self.gap=0.;self.cache={}
    def matrices(self,start):
        if start in self.cache:return self.cache[start]
        n=T-start;rr=[];cc=[];vv=[]
        for t in range(n):
            for col,val in [(t,1),(n+t,-1),(2*n+t,1),(3*n+t,-1)]:rr.append(t);cc.append(col);vv.append(val)
            for col,val in [(n+t,-ETA),(2*n+t,1/ETA),(4*n+t,1)]:rr.append(n+t);cc.append(col);vv.append(val)
            if t:rr.append(n+t);cc.append(4*n+t-1);vv.append(-1)
        A=coo_matrix((vv,(rr,cc)),shape=(2*n,6*n)).tocsr();ur=[];uc=[];uv=[]
        for t,p in enumerate(self.p[start:]):
            for row,f in [(t,.5),(n+t,1.5)]:ur.extend([row,row]);uc.extend([t,5*n+t]);uv.extend([f*p,-1])
        U=coo_matrix((uv,(ur,uc)),shape=(2*n,6*n)).tocsr()
        bounds=[(0,None)]*n+[(0,CAP)]*(2*n)+[(0,None)]*n+[(LO,HI)]*n+[(0,None)]*n
        bounds[5*n-1]=(self.target,self.target);self.cache[start]=(A,U,bounds);return self.cache[start]
    def solve(self,net,state,start=0,original=None):
        n=T-start;A,U,bounds=self.matrices(start);rhs=np.r_[net,np.zeros(n)];rhs[n]=state
        cost=np.r_[self.p[start:],np.zeros(5*n)] if original is None else np.r_[np.zeros(5*n),np.ones(n)]
        ub=None if original is None else np.r_[-.5*self.p[start:]*original,.5*self.p[start:]*original]
        uu=None if original is None else U
        r=linprog(cost,A_eq=A,b_eq=rhs,A_ub=uu,b_ub=ub,bounds=bounds,method='highs')
        if not r.success:raise RuntimeError(r.message)
        self.count+=1;self.residual=max(self.residual,float(abs(A@r.x-rhs).max()),0 if ub is None else float(np.maximum(U@r.x-ub,0).max()))
        dual=rhs@r.eqlin.marginals+np.array([a for a,b in bounds])@r.lower.marginals+np.array([b or 0 for a,b in bounds])@r.upper.marginals
        if ub is not None:dual+=ub@r.ineqlin.marginals
        self.gap=max(self.gap,float(abs(r.fun-dual)))
        x=r.x.reshape(6,n);return np.maximum(x[0],0),x[4].copy()

