def weighted_quantile(values,weights,alpha):
    if not len(values):return np.zeros(values.shape[-1])
    order=np.argsort(values,axis=0);x=np.take_along_axis(values,order,axis=0);w=np.take_along_axis(weights,order,axis=0)
    cum=np.cumsum(w,axis=0);idx=np.argmax(cum>=alpha*cum[-1],axis=0)
    return x[idx,np.arange(x.shape[1])]

def paths(data,fc,pf,d,hi,used,point,pred,cfg):
    last=d-2 if hi==0 else d-1
    idx=np.arange(max(14,last-cfg.window+1),last+1)
    if not len(idx):return np.zeros((0,T)),np.zeros((0,T)),idx
    ref=fc['historical'][idx] if cfg.source=='history' else fc['net'][idx,hi,used]
    errors=data.net[idx]-ref
    prices=np.maximum(pred[None,:]+data.P[idx]-pf[idx,hi],MIN_PRICE)
    if cfg.pricing=='fixed':prices=np.tile(data.baseP,(len(idx),1))
    if cfg.pricing=='oracle':prices=np.tile(data.P[d],(len(idx),1))
    return errors,prices,idx

def select(planner,point,errors,prices,pred,state,start,original,current,cfg):
    alpha=.8 if start==0 else .7
    if cfg.rule in ['point','quantile','weighted'] or not len(errors):
        correction=np.zeros(T)
        if len(errors) and cfg.rule!='point':
            correction=weighted_quantile(errors,prices if cfg.rule=='weighted' else np.ones_like(prices),alpha)
        q,E,a,b=planner.solve((point+correction)[start:],pred[start:],state,start,original)
        return q,E,f'{cfg.rule}:{alpha}',0.
    independent=cfg.rule=='independent'
    cand=[];value=cfg.value_scale*pred[-1]/ETA
    # Same feasible candidates for joint vs independent scores except weighting;
    # include both uniform and price-weighted curves to isolate ranking effects.
    for alpha in [.5,.7,.8,.9]:
        for weighting in ['plain','weighted']:
            correction=weighted_quantile(errors,prices if weighting=='weighted' else np.ones_like(prices),alpha)
            q,E,a,b=planner.solve((point+correction)[start:],pred[start:],state,start,original)
            val=score(q,point,errors,prices,state,start,original,value,independent)
            cand.append((val,q,E,f'{weighting}:{alpha}'))
    if current is not None:
        val=score(current,point,errors,prices,state,start,original,value,independent)
        cand.append((val,current.copy(),np.full(T-start,state),'keep'))
    best=min(cand,key=lambda c:c[0])
    return best[1],best[2],best[3],best[0]
